SELECT COUNT(*)
FROM h3_naver_statreport_daily
WHERE deltakey     = #{customerId}
  AND daily_dt     = #{date}
  AND report_type  = #{reportType}
  AND success      = true

SELECT jobid
FROM h3_naver_statreport_daily
WHERE deltakey = #{customerId}
  AND daily_dt = #{date}
  AND jobid   != ''

SELECT COUNT(*)
FROM h3_keyword_daily_naver_new
WHERE daily_advid = #{customerId}
  AND daily_dt    = #{date}

SELECT COUNT(*)
FROM h3_target_daily_naver
WHERE daily_advid = #{customerId}
  AND daily_dt    = #{date}
